"""## 8. Regla de decisión

El modelo de regresión no actúa por sí solo: su salida es un insumo para que el **equipo de operaciones y logística de la flota** decida cuántas bicicletas asignar y redistribuir por hora.

De acuerdo con el Canvas del proyecto, la regla operativa se define de la siguiente manera:
- **Horas punta en días laborales:** corresponden a los intervalos **07:00–09:00** (horas `7` y `8`) y **17:00–19:00** (horas `17` y `18`) cuando el registro corresponde a un **día laboral** (`dia_laboral`)[cite: 1, 2].
- **Margen de seguridad del 10%:** en esas franjas de alta demanda en días laborales, la cantidad planificada se calcula multiplicando la predicción base del modelo por **1,10** (`prediccion_planificada = prediccion_modelo * 1.10`)[cite: 1, 2].
- **Resto de horarios / días no laborales:** fuera de esas ventanas de alta presión laboral, se mantiene la predicción base sin el recargo del 10%, ayudando a evitar traslados innecesarios en horas valle o de menor exigencia[cite: 1, 2].

¿Por qué aplicar este 10% adicional en horas punta de días laborales? Porque el costo comercial y de experiencia de usuario asociado a un **quiebre de stock** en momentos de alta demanda supera al de mantener una disponibilidad extra moderada, mientras que en períodos de menor demanda conviene contener los costos operativos de redistribución[cite: 1, 2]. Asimismo, recordamos que esta estimación horaria orienta la planificación de la flota y no equivale mecánicamente al stock estacionado en cada estación, ya que una bicicleta puede rotar más de una vez dentro de la misma hora[cite: 1, 2].

A continuación implementamos la regla de decisión sobre las predicciones en validación y cuantificamos el ajuste aplicado[cite: 2].
"""

# ==============================================================================
# 8. REGLA DE DECISIÓN: MARGEN DEL 10% EN HORAS PUNTA DE DÍAS LABORALES
# ==============================================================================

def identificar_hora_punta_laboral(df_features):
    """
    Retorna una máscara booleana True para horas punta (07:00-09:00 -> horas 7, 8;
    17:00-19:00 -> horas 17, 18) en días laborales.
    """
    hora_num = pd.to_numeric(df_features["hora"], errors="coerce")
    es_hora_punta = ((hora_num >= 7) & (hora_num < 9)) | ((hora_num >= 17) & (hora_num < 19))

    if "dia_laboral" in df_features.columns:
        serie_lab = df_features["dia_laboral"]
        if pd.api.types.is_numeric_dtype(serie_lab):
            es_laboral = pd.to_numeric(serie_lab, errors="coerce") == 1
        else:
            texto_lab = serie_lab.astype(str).str.strip().str.lower()
            es_laboral = texto_lab.isin(["1", "true", "si", "sí", "laboral", "dia_laboral", "día laboral", "workingday"])
    else:
        # Respaldo si no existiera dia_laboral: usa dia_semana (lunes a viernes) y excluye feriado si existe
        es_laboral = pd.Series(True, index=df_features.index)
        if "dia_semana" in df_features.columns:
            texto_ds = df_features["dia_semana"].astype(str).str.strip().str.lower()
            es_laboral = ~texto_ds.isin(["5", "6", "sabado", "sábado", "domingo", "sunday", "saturday"])
        if "feriado" in df_features.columns:
            texto_fer = df_features["feriado"].astype(str).str.strip().str.lower()
            es_laboral = es_laboral & (~texto_fer.isin(["1", "true", "si", "sí", "feriado"]))

    return (es_hora_punta & es_laboral).fillna(False).to_numpy()


def aplicar_regla_decision(df_features, y_pred_base, margen_punta=0.10):
    """
    Aplica el margen de seguridad (por defecto +10%) sobre y_pred_base
    exclusivamente en horas punta (07:00-09:00 y 17:00-19:00) de días laborales.
    """
    y_pred = np.asarray(y_pred_base, dtype=float)
    mascara_punta_lab = identificar_hora_punta_laboral(df_features)
    factor = np.where(mascara_punta_lab, 1.0 + margen_punta, 1.0)
    y_planificada = y_pred * factor

    resultado = pd.DataFrame({
        "hora": pd.to_numeric(df_features["hora"], errors="coerce"),
        "dia_laboral": df_features["dia_laboral"] if "dia_laboral" in df_features.columns else np.nan,
        "es_punta_laboral": mascara_punta_lab,
        "prediccion_base": np.round(y_pred, 2),
        "factor_aplicado": factor,
        "prediccion_planificada": np.round(y_planificada, 2),
        "unidades_margen": np.round(y_planificada - y_pred, 2),
    }, index=df_features.index)

    return resultado


# Seleccionar modelo candidato de referencia (usa el mejor de validación si ya existe)
modelo_ref_nombre = mejor_modelo_nombre if "mejor_modelo_nombre" in globals() and "pipelines_entrenados" in globals() else None

if modelo_ref_nombre and modelo_ref_nombre in pipelines_entrenados:
    pred_base_val_modelo = pipelines_entrenados[modelo_ref_nombre].predict(X_val_mod)
    etiqueta_modelo = modelo_ref_nombre
elif "pred_base_val" in globals():
    pred_base_val_modelo = pred_base_val
    etiqueta_modelo = "Baseline (Mediana por hora)"
else:
    raise RuntimeError("Ejecuta primero la sección de Baseline (05) o Modelos (07) para contar con predicciones.")

df_decision_val = aplicar_regla_decision(X_val, pred_base_val_modelo, margen_punta=0.10)
df_decision_val["arriendos_reales"] = y_val.to_numpy()

print(f"Regla de decisión aplicada sobre predicciones de validación de: {etiqueta_modelo}")
display(df_decision_val.head(15))

# Resumen comparativo: Horas punta en días laborales vs. Resto de registros en validación
resumen_regla = (
    df_decision_val.groupby("es_punta_laboral")[
        ["arriendos_reales", "prediccion_base", "prediccion_planificada", "unidades_margen"]
    ]
    .agg(["count", "mean"])
    .round(2)
)

print("\nResumen promedio por régimen operativo (Validación):")
display(resumen_regla)

n_punta_lab = int(df_decision_val["es_punta_laboral"].sum())
total_val = len(df_decision_val)
margen_medio_punta = df_decision_val.loc[df_decision_val["es_punta_laboral"], "unidades_margen"].mean()

print("\n--- SÍNTESIS DE REGLA DE DECISIÓN EN VALIDACIÓN ---")
print(
    f"De {total_val:,} horas en validación, {n_punta_lab:,} ({n_punta_lab/total_val:.1%}) "
    f"corresponden a horas punta (07:00-09:00 y 17:00-19:00) en días laborales."
)
print(
    f"En esas franjas se añade en promedio +{margen_medio_punta:.2f} bicicletas/hora de margen "
    f"de seguridad (+10%) sobre la predicción base."
)

# Visualización: Predicción base vs. Predicción planificada en un día laboral típico de validación
muestra_lab = df_decision_val[df_decision_val["es_punta_laboral"]].copy()
if len(muestra_lab) > 0:
    por_hora_regla = (
        df_decision_val.groupby("hora")[["arriendos_reales", "prediccion_base", "prediccion_planificada"]]
        .mean()
        .sort_index()
    )

    plt.figure(figsize=(12, 5))
    plt.plot(por_hora_regla.index, por_hora_regla["arriendos_reales"], marker="o", label="Real promedio (validación)")
    plt.plot(por_hora_regla.index, por_hora_regla["prediccion_base"], marker="s", linestyle="--", label="Predicción base")
    plt.plot(por_hora_regla.index, por_hora_regla["prediccion_planificada"], marker="^", label="Predicción planificada (+10% punta laboral)")
    plt.title("Impacto de la regla de decisión horaria en Validación")
    plt.xlabel("Hora del día")
    plt.ylabel("Cantidad de arriendos / bicicletas")
    plt.xticks(range(24))
    plt.grid(alpha=0.3)
    plt.legend()
    plt.show()

"""### 8.1. Conclusión de la regla de decisión
La regla de decisión traduce la predicción horaria en una señal operativa concreta: sumar un **10% de margen de seguridad** únicamente en **horas punta (07:00–09:00 y 17:00–19:00) de días laborales**, priorizando la prevención de quiebres de stock cuando la presión de uso es mayor y evitando inflar la planificación en horarios de menor demanda[cite: 1, 2]. El paso siguiente es evaluar **09 · Riesgos y límites** y realizar la verificación final en el conjunto de prueba de manera controlada[cite: 2].

## 9. Riesgos y límites

Aun cuando el modelo se entrene con un flujo ordenado y sin fuga de datos, su uso operativo y analítico está sujeto a **riesgos** y **límites** que debemos explicitar para evitar decisiones mal calibradas[cite: 2]:

### 9.1. Riesgos operativos y del entorno
1. **Crecimiento interanual de usuarios entre 2011 y 2012 (*data drift*):** Entre 2011 y 2012 el sistema experimenta evolución y crecimiento en el uso, lo que altera los niveles y patrones históricos aprendidos en períodos anteriores[cite: 2]. Si el modelo subestima el nivel base de demanda del segundo año, puede generar subestimaciones sistemáticas (y mayor riesgo de quiebres de stock) en validación y prueba[cite: 2].
2. **Errores mayores ante eventos climáticos extremos:** Condiciones meteorológicas severas o poco frecuentes (lluvias intensas, tormentas, ráfagas o temperaturas extremas) tienen menor representación histórica y rompen los patrones habituales de movilidad, aumentando el margen de error del modelo[cite: 2].
3. **Dependencia de la precisión del pronóstico meteorológico:** En operación, el modelo se ejecuta antes de cada hora utilizando variables de clima pronosticado (`clima`, `temperatura_c`, `sensacion_termica_c`, `humedad_pct`, `velocidad_viento`)[cite: 2]. Si el pronóstico meteorológico se desvía del clima real que termina ocurriendo, la predicción de `arriendos_total` heredará ese error[cite: 2].

### 9.2. Límites analíticos e interpretativos
- **SHAP refleja asociación estadística, no causalidad directa:** Las explicaciones basadas en valores SHAP muestran cómo cada variable contribuye a la predicción del modelo en términos de asociación estadística dentro del conjunto de datos, **no** prueban causalidad directa en el mundo real ni garantizan que intervenir artificialmente sobre una variable produzca el efecto esperado en la demanda[cite: 2].
- **Flujo horario agregado vs. disponibilidad por estación:** `arriendos_total` estima arriendos horarios del sistema, no el inventario exacto por estación ni la rotación de bicicletas dentro de una misma hora, por lo que requiere criterio logístico complementario del equipo de operaciones[cite: 1, 2].

A continuación incorporamos un bloque de código para diagnosticar empíricamente el **cambio interanual (2011 vs. 2012)** y el **comportamiento del error según severidad climática** en los datos disponibles, junto con una estructura base para inspección de importancia/SHAP (con respaldo si `shap` no está instalado en el entorno de Colab)[cite: 2].
"""

# ==============================================================================
# 9. RIESGOS Y LÍMITES: DATA DRIFT (2011-2012), CLIMA EXTREMO Y LÍMITES SHAP
# ==============================================================================

target = "arriendos_total"
df_riesgos = bicicletas.copy()

# 1. Diagnóstico de crecimiento interanual / data drift entre años (ej. 2011 vs. 2012)
if "anio" in df_riesgos.columns:
    resumen_anual = (
        df_riesgos.groupby("anio")[target]
        .agg(["count", "mean", "median", "std", "max"])
        .round(2)
    )
    print("Comportamiento interanual de 'arriendos_total' (posible data drift):")
    display(resumen_anual)

    anios_ordenados = sorted(df_riesgos["anio"].dropna().unique())
    if len(anios_ordenados) >= 2:
        a_ini, a_fin = anios_ordenados[0], anios_ordenados[-1]
        media_ini = df_riesgos.loc[df_riesgos["anio"] == a_ini, target].mean()
        media_fin = df_riesgos.loc[df_riesgos["anio"] == a_fin, target].mean()
        var_pct = ((media_fin - media_ini) / media_ini) * 100 if media_ini != 0 else np.nan
        print(
            f"Variación promedio entre '{a_ini}' ({media_ini:.2f}) y '{a_fin}' ({media_fin:.2f}): "
            f"{var_pct:+.1f}%."
        )

# 2. Diagnóstico por condición climática ('clima') y percentiles extremos de temperatura/humedad/viento
if "clima" in df_riesgos.columns:
    resumen_clima = (
        df_riesgos.groupby("clima")[target]
        .agg(["count", "mean", "median"])
        .sort_values("mean", ascending=False)
        .round(2)
    )
    print("\nDemanda promedio y mediana según categoría de 'clima':")
    display(resumen_clima)

# Identificar horas con condiciones climáticas extremas (ej. humedad >= p95 o viento >= p95 o clima más adverso)
condiciones_extremas = pd.Series(False, index=df_riesgos.index)
if "humedad_pct" in df_riesgos.columns:
    umbral_hum = df_riesgos["humedad_pct"].quantile(0.95)
    condiciones_extremas = condiciones_extremas | (df_riesgos["humedad_pct"] >= umbral_hum)
if "velocidad_viento" in df_riesgos.columns:
    umbral_viento = df_riesgos["velocidad_viento"].quantile(0.95)
    condiciones_extremas = condiciones_extremas | (df_riesgos["velocidad_viento"] >= umbral_viento)

df_riesgos["escenario_climatico"] = np.where(
    condiciones_extremas, "Clima extremo (p95 humedad/viento)", "Condiciones habituales"
)
print("\nComparación de demanda en condiciones habituales vs. clima extremo (p95):")
display(
    df_riesgos.groupby("escenario_climatico")[target]
    .agg(["count", "mean", "median"])
    .round(2)
)

# Gráfico de evolución mensual / interanual si existen 'anio' y 'mes'
if all(c in df_riesgos.columns for c in ["anio", "mes"]):
    serie_mensual = (
        df_riesgos.groupby(["anio", "mes"])[target]
        .mean()
        .reset_index()
    )
    serie_mensual["periodo"] = (
        serie_mensual["anio"].astype(str) + "-" + serie_mensual["mes"].astype(str).str.zfill(2)
    )

    plt.figure(figsize=(13, 4.5))
    plt.plot(serie_mensual["periodo"], serie_mensual[target], marker="o")
    plt.title("Evolución de la demanda horaria promedio por mes y año (Data Drift)")
    plt.xlabel("Período (Año-Mes)")
    plt.ylabel("Promedio de arriendos_total")
    plt.xticks(rotation=45, ha="right")
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

# 3. Evaluación de error en Validación si existe un modelo entrenado en el notebook
if "mejor_modelo_nombre" in globals() and "pipelines_entrenados" in globals():
    from sklearn.metrics import mean_absolute_error, root_mean_squared_error

    pipe_sel = pipelines_entrenados[mejor_modelo_nombre]
    pred_val_sel = pipe_sel.predict(X_val_mod)

    diag_val = X_val.copy()
    diag_val["y_real"] = y_val.to_numpy()
    diag_val["y_pred"] = pred_val_sel
    diag_val["error_abs"] = np.abs(diag_val["y_real"] - diag_val["y_pred"])

    if "clima" in diag_val.columns:
        error_por_clima = (
            diag_val.groupby("clima")
            .apply(lambda g: pd.Series({
                "n_horas": len(g),
                "MAE": round(mean_absolute_error(g["y_real"], g["y_pred"]), 2),
                "RMSE": round(root_mean_squared_error(g["y_real"], g["y_pred"]), 2),
            }), include_groups=False)
        )
        print(f"\nError en Validación por 'clima' ({mejor_modelo_nombre}):")
        display(error_por_clima)

    # 4. Apoyo interpretativo SHAP (con respaldo si 'shap' no está instalado)
    # Recordatorio: SHAP refleja asociación estadística, no causalidad directa.
    try:
        import shap
        preproc_ajustado = pipe_sel.named_steps["preprocesador"]
        modelo_ajustado = pipe_sel.named_steps["modelo"]
        X_val_trans = preproc_ajustado.transform(X_val_mod)
        nombres_features = preproc_ajustado.get_feature_names_out()

        muestra_n = min(300, len(X_val_trans))
        explainer = shap.Explainer(modelo_ajustado, X_val_trans[:muestra_n])
        shap_vals = explainer(X_val_trans[:muestra_n])

        shap.summary_plot(
            shap_vals.values,
            X_val_trans[:muestra_n],
            feature_names=nombres_features,
            max_display=12,
            show=True,
        )
    except ImportError:
        print(
            "\nNota: la librería 'shap' no está instalada en este entorno. "
            "Para calcular valores SHAP en Colab puedes ejecutar: !pip install -q shap. "
            "Recuerda que SHAP mide asociación estadística de las variables en el modelo, no causalidad."
        )

# ==============================================================================
# 9. RIESGOS Y LÍMITES: DATA DRIFT (2011-2012), CLIMA EXTREMO Y LÍMITES SHAP
# ==============================================================================

target = "arriendos_total"
df_riesgos = bicicletas.copy()

# 1. Diagnóstico de crecimiento interanual / data drift entre años (ej. 2011 vs. 2012)
if "anio" in df_riesgos.columns:
    resumen_anual = (
        df_riesgos.groupby("anio")[target]
        .agg(["count", "mean", "median", "std", "max"])
        .round(2)
    )
    print("Comportamiento interanual de 'arriendos_total' (posible data drift):")
    display(resumen_anual)

    anios_ordenados = sorted(df_riesgos["anio"].dropna().unique())
    if len(anios_ordenados) >= 2:
        a_ini, a_fin = anios_ordenados[0], anios_ordenados[-1]
        media_ini = df_riesgos.loc[df_riesgos["anio"] == a_ini, target].mean()
        media_fin = df_riesgos.loc[df_riesgos["anio"] == a_fin, target].mean()
        var_pct = ((media_fin - media_ini) / media_ini) * 100 if media_ini != 0 else np.nan
        print(
            f"Variación promedio entre '{a_ini}' ({media_ini:.2f}) y '{a_fin}' ({media_fin:.2f}): "
            f"{var_pct:+.1f}%."
        )

# 2. Diagnóstico por condición climática ('clima') y percentiles extremos de temperatura/humedad/viento
if "clima" in df_riesgos.columns:
    resumen_clima = (
        df_riesgos.groupby("clima")[target]
        .agg(["count", "mean", "median"])
        .sort_values("mean", ascending=False)
        .round(2)
    )
    print("\nDemanda promedio y mediana según categoría de 'clima':")
    display(resumen_clima)

# Identificar horas con condiciones climáticas extremas (ej. humedad >= p95 o viento >= p95 o clima más adverso)
condiciones_extremas = pd.Series(False, index=df_riesgos.index)
if "humedad_pct" in df_riesgos.columns:
    umbral_hum = df_riesgos["humedad_pct"].quantile(0.95)
    condiciones_extremas = condiciones_extremas | (df_riesgos["humedad_pct"] >= umbral_hum)
if "velocidad_viento" in df_riesgos.columns:
    umbral_viento = df_riesgos["velocidad_viento"].quantile(0.95)
    condiciones_extremas = condiciones_extremas | (df_riesgos["velocidad_viento"] >= umbral_viento)

df_riesgos["escenario_climatico"] = np.where(
    condiciones_extremas, "Clima extremo (p95 humedad/viento)", "Condiciones habituales"
)
print("\nComparación de demanda en condiciones habituales vs. clima extremo (p95):")
display(
    df_riesgos.groupby("escenario_climatico")[target]
    .agg(["count", "mean", "median"])
    .round(2)
)

# Gráfico de evolución mensual / interanual si existen 'anio' y 'mes'
if all(c in df_riesgos.columns for c in ["anio", "mes"]):
    serie_mensual = (
        df_riesgos.groupby(["anio", "mes"])[target]
        .mean()
        .reset_index()
    )
    serie_mensual["periodo"] = (
        serie_mensual["anio"].astype(str) + "-" + serie_mensual["mes"].astype(str).str.zfill(2)
    )

    plt.figure(figsize=(13, 4.5))
    plt.plot(serie_mensual["periodo"], serie_mensual[target], marker="o")
    plt.title("Evolución de la demanda horaria promedio por mes y año (Data Drift)")
    plt.xlabel("Período (Año-Mes)")
    plt.ylabel("Promedio de arriendos_total")
    plt.xticks(rotation=45, ha="right")
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

# 3. Evaluación de error en Validación si existe un modelo entrenado en el notebook
if "mejor_modelo_nombre" in globals() and "pipelines_entrenados" in globals():
    from sklearn.metrics import mean_absolute_error, root_mean_squared_error

    pipe_sel = pipelines_entrenados[mejor_modelo_nombre]
    pred_val_sel = pipe_sel.predict(X_val_mod)

    diag_val = X_val.copy()
    diag_val["y_real"] = y_val.to_numpy()
    diag_val["y_pred"] = pred_val_sel
    diag_val["error_abs"] = np.abs(diag_val["y_real"] - diag_val["y_pred"])

    if "clima" in diag_val.columns:
        error_por_clima = (
            diag_val.groupby("clima")
            .apply(lambda g: pd.Series({
                "n_horas": len(g),
                "MAE": round(mean_absolute_error(g["y_real"], g["y_pred"]), 2),
                "RMSE": round(root_mean_squared_error(g["y_real"], g["y_pred"]), 2),
            }), include_groups=False)
        )
        print(f"\nError en Validación por 'clima' ({mejor_modelo_nombre}):")
        display(error_por_clima)

    # 4. Apoyo interpretativo SHAP (con respaldo si 'shap' no está instalado)
    # Recordatorio: SHAP refleja asociación estadística, no causalidad directa.
    try:
        import shap
        preproc_ajustado = pipe_sel.named_steps["preprocesador"]
        modelo_ajustado = pipe_sel.named_steps["modelo"]
        X_val_trans = preproc_ajustado.transform(X_val_mod)
        nombres_features = preproc_ajustado.get_feature_names_out()

        muestra_n = min(300, len(X_val_trans))
        explainer = shap.Explainer(modelo_ajustado, X_val_trans[:muestra_n])
        shap_vals = explainer(X_val_trans[:muestra_n])

        shap.summary_plot(
            shap_vals.values,
            X_val_trans[:muestra_n],
            feature_names=nombres_features,
            max_display=12,
            show=True,
        )
    except ImportError:
        print(
            "\nNota: la librería 'shap' no está instalada en este entorno. "
            "Para calcular valores SHAP en Colab puedes ejecutar: !pip install -q shap. "
            "Recuerda que SHAP mide asociación estadística de las variables en el modelo, no causalidad."
        )

